import csv
import json
import os
from pathlib import Path

def generate_dataset(spectra_output_dir: Path, output_csv: Path):
    """
    Parses all output directories from SPECTRA runs and aggregates 
    candidate evaluation data into a single training CSV.
    """
    dataset_rows = []
    
    # Iterate through all subdirectories (each represents one function optimization)
    for run_dir in spectra_output_dir.iterdir():
        if not run_dir.is_dir():
            continue
            
        # Look for the candidates CSV generated by SPECTRA
        candidates_csv = run_dir / f"{run_dir.name}_candidates.csv"
        
        if not candidates_csv.exists():
            print(f"Skipping {run_dir.name}: No candidates CSV found.")
            continue
            
        print(f"Processing {run_dir.name}...")
        
        with open(candidates_csv, 'r') as f:
            reader = csv.DictReader(f)
            for row in reader:
                # We only care about confirmed F3 ground truth measurements
                # F3 is the most reliable (lowest variance) signal
                if row.get('f3_mj') and float(row['f3_mj']) > 0:
                    
                    # Reconstruct the transformation chain
                    # SPECTRA doesn't save the full chain in the CSV, 
                    # so we look at the source and assume an empty list for base
                    # or you can reconstruct it from the iteration records if needed.
                    chain = [{"operator": row['operator'], "tier": row['tier'], "needs_llm": row['is_llm'] == 'True'}]
                    
                    dataset_rows.append({
                        'source': row['transformed_source'],
                        'chain_json': json.dumps(chain),
                        'energy_mJ': row['f3_mj'],
                        'std_mJ': row.get('f3_std_mj', 0.0),
                        'n_samples': 20 # Standard SPECTRA F3 reps
                    })

    # Write to CSV
    keys = ['source', 'chain_json', 'energy_mJ', 'std_mJ', 'n_samples']
    with open(output_csv, 'w', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=keys)
        writer.writeheader()
        writer.writerows(dataset_rows)
    
    print(f"\nSuccessfully generated {len(dataset_rows)} samples in {output_csv}")

if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("--dir", required=True, help="Directory containing your spectra_output subfolders")
    parser.add_argument("--out", default="training_data.csv", help="Output CSV path")
    args = parser.parse_args()
    
    generate_dataset(Path(args.dir), Path(args.out))